#!/usr/bin/env python3# -*- coding: utf-8 -*-"""Database loading and cleaning for the iPHAsimulatorV2 GUI."""import pandas as pdimport streamlit as stfrom gui.config import (    RESIDUE_CODES_CSV,    paths,)from gui.models import GUIData@st.cache_datadef load_available_PHA_monomers(    residue_codes_csv,    modified_time,):    """    Load registered PHA monomers from residue_codes.csv.    modified_time is used to invalidate the Streamlit cache when    the CSV changes.    """    del modified_time    df = pd.read_csv(        residue_codes_csv    )    required_columns = {        "PHA_type",        "component",        "smiles",    }    missing_columns = (        required_columns        - set(df.columns)    )    if missing_columns:        raise ValueError(            "residue_codes.csv is missing required columns:\n"            + "\n".join(                sorted(missing_columns)            )        )    mainchain_df = df[        df["component"] == "mainchain"    ].copy()    mainchain_df = mainchain_df.dropna(        subset=[            "PHA_type",            "smiles",        ]    )    mainchain_df["PHA_type"] = (        mainchain_df["PHA_type"]        .astype(str)        .str.strip()    )    mainchain_df["smiles"] = (        mainchain_df["smiles"]        .astype(str)        .str.strip()    )    mainchain_df = mainchain_df[        (            mainchain_df["PHA_type"] != ""        )        & (            mainchain_df["smiles"] != ""        )    ]    mainchain_df = mainchain_df.drop_duplicates(        subset=["PHA_type"],        keep="last",    )    mainchain_df = mainchain_df.sort_values(        by="PHA_type"    ).reset_index(        drop=True    )    available_phas = (        mainchain_df["PHA_type"]        .tolist()    )    monomer_smiles = {        row["PHA_type"]: row["smiles"]        for _, row in mainchain_df.iterrows()    }    return (        available_phas,        monomer_smiles,        mainchain_df,    )def load_registered_md_systems():    """    Load and clean md_systems.csv through PHAFileManager.    """    systems = paths.load_md_systems()    columns = [        "system_name",        "system_type",        "number_of_atoms",    ]    if not systems:        return pd.DataFrame(            columns=columns        )    systems_df = pd.DataFrame(        systems    )    for column in columns:        if column not in systems_df.columns:            systems_df[column] = ""    systems_df = systems_df[        columns    ].copy()    systems_df["system_name"] = (        systems_df["system_name"]        .fillna("")        .astype(str)        .str.strip()    )    systems_df["system_type"] = (        systems_df["system_type"]        .fillna("")        .astype(str)        .str.strip()    )    systems_df["number_of_atoms"] = pd.to_numeric(        systems_df["number_of_atoms"],        errors="coerce",    )    systems_df = systems_df[        systems_df["system_name"] != ""    ]    systems_df = systems_df.drop_duplicates(        subset=["system_name"],        keep="last",    )    systems_df = systems_df.sort_values(        by=[            "system_type",            "system_name",        ]    ).reset_index(        drop=True    )    return systems_dfdef load_gui_data():    """    Load all database information required by the GUI.    """    residue_modified_time = (        RESIDUE_CODES_CSV.stat().st_mtime        if RESIDUE_CODES_CSV.exists()        else 0    )    (        available_phas,        monomer_smiles,        mainchain_df,    ) = load_available_PHA_monomers(        RESIDUE_CODES_CSV,        residue_modified_time,    )    md_systems_df = (        load_registered_md_systems()    )    return GUIData(        paths=paths,        available_phas=available_phas,        monomer_smiles=monomer_smiles,        mainchain_df=mainchain_df,        md_systems_df=md_systems_df,    )